export const LANGUAGE_IDS = new Set(LANGUAGES.map(p=>p.id));
export const isLanguage = id=>LANGUAGE_IDS.has(id);
export const languageName = id=>LANGUAGES.find(p=>p.id===id)?.name||id;
export const languageSource = id=>LANGUAGES.find(p=>p.id===id)?.sourceUrl||'https://www.sign-lang.uni-hamburg.de/lr/compendium/';
export function populateLanguageSelects(ids){for(const id of ids){const select=document.getElementById(id);if(!select)continue;const previous=select.value;select.replaceChildren();for(const p of [...LANGUAGES].sort((a,b)=>a.name.localeCompare(b.name))){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+(p.aliases?.length?' · '+p.aliases[0]:'');select.append(option);}select.value=isLanguage(previous)?previous:'ASL';}}
